// Vulnerable (JavaScript, Express: a Node.js web server framework): the client sets its own role
app.get("/admin/users", (req, res) => {
  if (req.cookies.role === "admin") {        // attacker sets role=admin
    return res.json(listAllUsers());
  }
  res.sendStatus(403);
});

// Fixed: the role comes from server-side state tied to a verified session
app.get("/admin/users", requireSession, (req, res) => {
  const user = users.findById(req.session.userId);   // looked up on the server
  if (user && user.role === "admin") {
    return res.json(listAllUsers());
  }
  res.sendStatus(403);
});

