def cost(node):
    if "cost" in node:                      # leaf
        return node["cost"]
    kids = [cost(k) for k in node["kids"]]
    return min(kids) if node["type"] == "OR" else sum(kids)

stuffing = {"type": "AND", "kids": [{"cost": 200}]}
phishing = {"type": "AND", "kids": [{"cost": 300}]}
account  = {"type": "OR",  "kids": [stuffing, phishing]}
url_trick = {"type": "AND", "kids": [{"cost": 0}, {"cost": 500}]}
db_direct = {"type": "AND", "kids": [{"cost": 3000}, {"cost": 5000}]}
root = {"type": "OR", "kids": [account, url_trick, db_direct, {"cost": 20000}]}
print(cost(root))                           # 200

for path in (stuffing, phishing):           # MFA now required on every login
    path["kids"].append({"cost": 2000})
print(cost(root))                           # 500, the URL trick is cheapest

root["kids"].remove(url_trick)              # ownership check added
print(cost(root))                           # 2200

# Exclusion (deny-list): says who may NOT delete
BLOCKED = {"guest", "suspended"}
def can_delete_deny(role):
    return role not in BLOCKED          # unknown roles are allowed

# Permission (allowlist): says who MAY delete
ALLOWED = {"owner", "admin"}
def can_delete_allow(role):
    return role in ALLOWED              # unknown roles are refused

