// Before (JavaScript, Express): each handler carries its own check
app.get("/notes/:id", requireLogin, async (req, res) => {
  const note = await db.notes.find(req.params.id);
  if (!note || note.ownerId !== req.user.id) return res.sendStatus(404);
  res.json(note);
});
app.get("/export/:id", requireLogin, async (req, res) => {
  const note = await db.notes.find(req.params.id);   // ownership check forgotten
  res.attachment("note.txt").send(note.body);
});

// After: one check, run for every route that takes a note id
const notes = express.Router();
notes.use(requireLogin);
notes.param("id", async (req, res, next, id) => {
  const note = await db.notes.find(id);
  if (!note || note.ownerId !== req.user.id) return res.sendStatus(404);
  req.note = note;            // handlers only ever see an authorized note
  next();
});
notes.get("/notes/:id", (req, res) => res.json(req.note));
notes.get("/export/:id", (req, res) => res.attachment("note.txt").send(req.note.body));
app.use(notes);

-- Before: the app logs in as the PostgreSQL (open-source database) superuser, its all-powerful admin role
--   it can read every table, drop tables, and read server files

-- After: a role with only what the notes API needs
CREATE ROLE notes_app LOGIN PASSWORD 'loaded-from-secret-store';
GRANT CONNECT ON DATABASE notes TO notes_app;
GRANT USAGE ON SCHEMA public TO notes_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON notes, attachments TO notes_app;
GRANT SELECT (id, email, display_name) ON users TO notes_app;
GRANT USAGE ON SEQUENCE notes_id_seq, attachments_id_seq TO notes_app;  -- if ids are serial
-- no billing tables, no password_hash column, no DDL, no superuser;
-- the login service uses a separate role that can read password_hash

# Segmentation as a default-deny policy: which zone may open connections to which
ALLOWED = {
    "vendor-portal": {"billing-app"},
    "billing-app":   {"billing-db"},
    "pos":           {"payment-processor"},
}

def may_connect(src_zone, dst_zone):
    return dst_zone in ALLOWED.get(src_zone, set())   # anything unlisted is refused

print(may_connect("vendor-portal", "billing-app"))   # True
print(may_connect("vendor-portal", "pos"))           # False

// Before (JavaScript, Express): trust by network location
app.use("/admin", (req, res, next) => {
  if (req.ip.startsWith("10.")) return next();    // "inside" means trusted
  res.sendStatus(403);
});

// After: every request proves who is asking, from what device, for what
app.use("/admin", async (req, res, next) => {
  const session = await verifySessionToken(req.get("Authorization"));
  if (!session) return res.sendStatus(401);
  const decision = await policy.decide({         // the policy decision point
    user: session.userId, mfa: session.mfa,
    device: session.deviceId, resource: req.path, action: req.method,
  });
  if (decision !== "allow") return res.sendStatus(403);
  next();                                          // this middleware is the PEP
});

